class UnitOfWork
{
    private readonly HashSet<string> _new = new(), _dirty = new(), _removed = new();
    public void RegisterNew(string id) => _new.Add(id);
    public void RegisterDirty(string id) { if (!_new.Contains(id)) _dirty.Add(id); }
    public void RegisterRemoved(string id)
    {
        if (_new.Remove(id)) return;
        _dirty.Remove(id);
        _removed.Add(id);
    }
    public string Commit() => $"insert={_new.Count} update={_dirty.Count} delete={_removed.Count}";
}

