import "fmt"

type sub struct {
	id int
	fn func(string)
}

type Bus struct {
	nextID int
	subs   []sub
}

func (b *Bus) Subscribe(fn func(string)) int {
	b.nextID++
	b.subs = append(b.subs, sub{b.nextID, fn})
	return b.nextID
}

func (b *Bus) Unsubscribe(id int) {
	for i, s := range b.subs {
		if s.id == id {
			b.subs = append(b.subs[:i], b.subs[i+1:]...)
			return
		}
	}
}

func (b *Bus) Publish(msg string) {
	for _, s := range b.subs {
		s.fn(msg)
	}
}

