	bus := &Bus{}
	idA := bus.Subscribe(func(string) { a++ })
	bus.Subscribe(func(string) { b++ })
	bus.Publish("x")
	bus.Unsubscribe(idA)
	bus.Subscribe(func(string) { c++ })
	bus.Publish("y")
	bus.Publish("z")
	fmt.Println(a, b, c)
