var shapes = new Shape[]
{
    new Circle(new Svg(), 2),
    new Circle(new Ascii(), 2),
    new Box(new Svg(), 3),
    new Box(new Ascii(), 3),
};
foreach (var s in shapes) Console.WriteLine(s.Draw());

interface IRenderer { string Circle(int r); string Box(int w); }
class Svg : IRenderer
{
    public string Circle(int r) => $"<circle r={r}/>";
    public string Box(int w) => $"<rect w={w}/>";
}
class Ascii : IRenderer
{
    public string Circle(int r) => $"O{r}";
    public string Box(int w) => new string('#', w);
}
abstract class Shape(IRenderer renderer)
{
    protected IRenderer Renderer => renderer;
    public abstract string Draw();
}
class Circle(IRenderer r, int radius) : Shape(r) { public override string Draw() => Renderer.Circle(radius); }
class Box(IRenderer r, int width) : Shape(r) { public override string Draw() => Renderer.Box(width); }

class Shape { area() { return 0; } }
class Rect extends Shape {
  constructor(w, h) { super(); this.w = w; this.h = h; }
  area() { return this.w * this.h; }
}
class Circle extends Shape {
  constructor(r) { super(); this.r = r; }
  area() { return 3 * this.r ** 2; }
}
class Triangle extends Shape {
  constructor(b, h) { super(); this.b = b; this.h = h; }
}

const total = (shapes) => shapes.reduce((sum, s) => sum + s.area(), 0);
console.log(total([new Rect(2, 3), new Circle(2)]));
console.log(total([new Rect(2, 3), new Circle(2), new Triangle(4, 5)]));

